def main() -> None:
    for s in SKILLS:
        examples = []
        for prompt, lang, extra in s["ex"]:
            e: dict = {"prompt": prompt, "lang": lang}
            extra = dict(extra or {})
            if "_also" in extra:
                e["also"] = extra.pop("_also")
            if extra:
                e["params"] = extra
            examples.append(e)
        params = {k: {kk: vv for kk, vv in v.items() if vv is not None} for k, v in s["params"].items()}
        doc = {
            "id": s["id"], "seed": s["seed"], "category": "text", "name": s["name"], "name_hi": s["name_hi"],
            "description": s["desc"], **({"same_engine_as": s["same_engine_as"]} if "same_engine_as" in s else {}),
            "params": params, "time_modes": s["modes"], "builder": f"text.{s['id']}", "graph": s["graph"],
            "media3": s["media3"], "stage": "text" if s["id"] not in ("watermark_logo", "progress_bar") else "overlay",
            "conflicts": [], "cost": "medium" if s["id"] in ("auto_captions", "karaoke_captions") else "cheap",
            "licence": "own code; libass + HarfBuzz via FFmpeg (server process); fonts SIL OFL (Hind, Kalam, Poppins, Anton, Bebas)",
            "changes_duration": s["id"] == "title_card", "needs": s["needs"], "variant_axes": s["axes"],
            "synonyms": s["syn"], "negations": s["neg"], "examples": examples, "test": s["test"],
        }
        (OUT / f"{s['id']}.yaml").write_text("# written by skills/tools/write_tier1_text.py — edit this file directly from now on\n"
                                             + yaml.safe_dump(doc, allow_unicode=True, sort_keys=False, width=120), encoding="utf-8")
        print(s["id"])


if __name__ == "__main__":
    main()
